/**
 * Private object storage for exports (S5-2, D-005, Ruling 4). Keys are relative paths (`exports/{org}/{job}/x.csv`).
 * Nothing here is ever public: the app streams objects to the one user allowed to download them.
 */
export interface StoragePort {
  put(key: string, body: string, contentType: string): Promise<void>;
  /** The object's bytes, or null when it doesn't exist. */
  read(key: string): Promise<Buffer | null>;
  /** Removes the objects (missing ones are fine). */
  deleteMany(keys: string[]): Promise<void>;
}

/** Keys are generated by the app; this refuses anything that could escape its prefix. */
export function assertSafeKey(key: string): void {
  if (
    !/^[A-Za-z0-9][A-Za-z0-9/_.-]{0,500}$/.test(key) ||
    key.includes('..') ||
    key.includes('//')
  ) {
    throw new Error(`Invalid storage key: ${key}`);
  }
}
